const row = $json;
// Replace this placeholder with the joined Birdeye/DexScreener history.
// Never label from a single current-price response.
if (!row.history || !Array.isArray(row.history)) return [{ json: { ...row, label: null, status: 'excluded_insufficient_data', reason_code: 'missing_history', label_rules_version: 'v1' } }];
const peak = Math.max(...row.history.map((p) => Number(p.value)).filter(Number.isFinite));
const early = row.history.filter((p) => Number(p.days) <= 7).map((p) => Number(p.value)).filter(Number.isFinite);
const at30 = row.history.find((p) => Number(p.days) >= 30)?.value;
const rugged = peak >= 5000 && (Math.min(...early) <= peak * 0.1 || row.confirmed_lp_removal === true);
const survived = peak >= 5000 && Number(at30) >= peak * 0.5;
const status = rugged ? 'rugged' : survived ? 'survived' : 'excluded_ambiguous';
return [{ json: { ...row, label: rugged ? 1 : survived ? 0 : null, status, reason_code: rugged || survived ? null : 'ambiguous_slow_bleed', label_rules_version: 'v1' } }];
